// todo 需要分布式锁保护的代码
rlock.Dispose(); // 释放锁。也可以在using语句结束时自动释放

using var rlock = cache.AcquireLock("myKey", 5000, 15000, false);
if (rlock == null) throw new Exception("申请锁失败！");
// todo 需要分布式锁保护的代码
rlock.Dispose(); // 释放锁。也可以在using语句结束时自动释放

